def canSeePersonsCount(heights):
    m, n = len(heights), len(heights[0])
    answer = [[0] * n for _ in range(m)]

    # For each row: look right
    for i in range(m):
        stack = []
        # Go from right to left for right-visibility
        for j in range(n-1, -1, -1):
            count = 0
            while stack and heights[i][j] > stack[-1][0]:
                count += 1
                stack.pop()
            if stack:
                count += 1  # can see the first taller/equal on stack
                if stack[-1][0] == heights[i][j]:
                    stack.pop()  # equal height blocks the view of anything behind it
            answer[i][j] += count
            stack.append((heights[i][j], j))

    # For each column: look down
    for j in range(n):
        stack = []
        for i in range(m-1, -1, -1):
            count = 0
            while stack and heights[i][j] > stack[-1][0]:
                count += 1
                stack.pop()
            if stack:
                count += 1
                if stack[-1][0] == heights[i][j]:
                    stack.pop()
            answer[i][j] += count
            stack.append((heights[i][j], i))
    return answer
